import React, { useState } from 'react';
import { PanelMenu } from 'primereact/panelmenu';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="panelMenu-accessibility">Accessible PanelMenu</label>
            <PanelMenu 
                id="panelMenu-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible PanelMenu input"
                placeholder="Enter panelMenu"
            />
        </div>
    );
}